package com.saasquatch.intelligence.controller;
import com.saasquatch.intelligence.entity.*;import com.saasquatch.intelligence.repository.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/accounts") @CrossOrigin(origins="*") public class AccountController{final CompanyRepository companies;final CorporateRelationshipRepository rels;public AccountController(CompanyRepository c,CorporateRelationshipRepository r){companies=c;rels=r;}@GetMapping("/{id}/relationships") public Map<String,Object> get(@PathVariable Long id){Company c=companies.findById(id).orElseThrow();List<Map<String,Object>> a=new ArrayList<>();for(CorporateRelationship r:rels.findByCompanyId(id))a.add(Map.of("companyId",r.getRelatedCompany().getId(),"companyName",r.getRelatedCompany().getName(),"relationshipType",r.getType().name(),"confidence",98));return Map.of("companyId",c.getId(),"companyName",c.getName(),"relatedCompanies",a);}}